await page.evaluate(async () => {
  const r = await fetch('/robots.txt');
  const robotsOk = r.ok;
  const robotsText = robotsOk ? await r.text() : '';
  const sitemaps = robotsText.split(/\n/).filter(l => /^\s*Sitemap:/i.test(l)).map(l => l.replace(/^\s*Sitemap:\s*/i, '').trim());
  const sr = await fetch('/sitemap.xml');
  let locCount = 0, allSame = true;
  if (sr.ok) {
    const xml = await sr.text();
    const doc = new DOMParser().parseFromString(xml, 'application/xml');
    const locs = [...doc.getElementsByTagName('loc')].map(e => e.textContent.trim());
    locCount = locs.length;
    const host = location.hostname;
    allSame = locs.every(u => { try { return new URL(u).hostname === host; } catch { return false; } });
  } else { allSame = false; }
  window.__bench_finding = { robotsPresent: robotsOk, robotsSitemaps: sitemaps.sort(), sitemapUrlCount: locCount, allSameHost: allSame };
});

